CREATE TABLE public."transactions" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME public."transactions_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
  "transaction_date" date NOT NULL,
  "transaction_type" text NOT NULL,
  "amount" numeric(14,2) NOT NULL,
  "currency" text DEFAULT 'RUB'::text NOT NULL,
  "description" text NOT NULL,
  "category_id" bigint,
  "from_account_id" bigint,
  "to_account_id" bigint,
  "liability_id" bigint,
  "external_ref" text,
  "notes" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "occurred_at" timestamp with time zone NOT NULL,
  "budget_effect" text NOT NULL,
  "salary_component" text,
  "salary_period_start" date,
  "income_event_id" bigint,
  "request_payload" jsonb,
  "reserve_effect" text DEFAULT 'none'::text NOT NULL,
  "reserve_cycle" text,
  "reserve_due_date" date,
  "reserve_liability_id" bigint
);
